/*
 * Demonstrates using the reboot() library wrapper to initiate a system power off.
 * NOTE: This program MUST be run with root privileges.
 */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/reboot.h>
#include <errno.h>

int main(void) {
    printf("Attempting to initiate system power off (RB_POWER_OFF)...
");
    printf("This requires the CAP_SYS_BOOT capability (usually root access).
");

    // RB_POWER_OFF command tells the kernel to turn off the system power.
    // Use RB_RESTART for a standard reboot.
    int status = reboot(RB_POWER_OFF);

    if (status == -1) {
        perror("reboot failed");
        if (errno == EPERM) {
            fprintf(stderr, "Error: Permission denied. Must be run as root.
");
        } else if (errno == EINVAL) {
             fprintf(stderr, "Error: Invalid command argument provided.
");
        }
        return EXIT_FAILURE;
    }

    // If reboot is successful, the process is terminated immediately by the kernel.
    // This line should typically not be reached.
    printf("Reboot signal sent successfully (System should be shutting down now).
");
    return EXIT_SUCCESS;
}
